import type { AutogeneratedInsertableClientContact, AutogeneratedClientContact } from './autogenerated/autogenerated_client_contact.d.ts'

export type ArbostarEmailData = {
	email_check: 0 | 1 | null
	email_manual_approve: 0 | 1
	email_blocked: boolean
	email_blocked_reason: 'COMPLAINT' | 'BOUNCE' | null
	email_blocked_date: string | null
	email_unsubscribed: boolean
	email_unsubscribe: {
		email: string
		documentation: boolean
		informational: boolean
		reason: null
	} | null
}

type ArbostarEmailDataField = { arbostar_email_data: ArbostarEmailData | null }

declare global {
	type DbInsertableClientContact = Omit<AutogeneratedInsertableClientContact, keyof ArbostarEmailDataField> & ArbostarEmailDataField
	type DbClientContact = Omit<AutogeneratedClientContact, keyof ArbostarEmailDataField> & ArbostarEmailDataField
}
